md<-qread(out('00_audit/cell_metadata.qs'));tot<-qread(file.path(v3,'04_pseudobulk_markers/sample_totals.qs'));samples<-tot$meta$sample;ids<-md$cell_id;selected<-md[cluster=='C14'];input<-yaml::read_yaml(file.path(v3,'CONFIG.yaml'))$input
logmsg('Load original RNA once; aggregate only frozen C14');s<-qread(input,nthreads=2);stopifnot(setequal(colnames(s),ids));layers<-Layers(s[['RNA']]);cl<-grep('^counts($|\\.)',layers,value=TRUE);stopifnot(length(cl)==1);x<-LayerData(s[['RNA']],layer=cl)[,selected$cell_id,drop=FALSE];stopifnot(inherits(x,'sparseMatrix'),all(is.finite(x@x)),all(x@x>=0),all(x@x==floor(x@x)),identical(rownames(x),rownames(tot$counts)));lib<-colSums(x);stopifnot(all(lib>0),all(lib==selected$nCount_RNA),all(colSums(x>0)==selected$nFeature_RNA));y<-LayerData(s[['RNA']],layer='data')[,selected$cell_id,drop=FALSE];t<-x%*%Diagonal(x=1e4/lib);dimnames(t)<-dimnames(x);t@x<-log1p(t@x);diff<-max(abs(y-t));if(diff>1e-6)y<-t;rm(s,t);gc();det<-drop0(x);det@x[]<-1
